import{_ as e,o as l,a as t,b as i}from"./app.C41L12d5.js";const n="/ascendc.github.io/assets/ai_cpu_hw.CyGzc8Hr.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI CPU编程","link":"/guide/programming_guide/programming_model/ai_cpu_programming"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_cpu_programming.md","filePath":"guide/programming_guide/programming_model/ai_cpu_programming.md","outlineHeaders":[{"level":2,"title":"AI CPU核函数（Kernel）定义","slug":"AI-CPU核函数（Kernel）定义","link":"#AI-CPU核函数（Kernel）定义"},{"level":2,"title":"AI CPU核函数（Kernel）调用","slug":"AI-CPU核函数（Kernel）调用","link":"#AI-CPU核函数（Kernel）调用"},{"level":2,"title":"AI CPU模板核函数（Kernel）","slug":"AI-CPU模板核函数（Kernel）","link":"#AI-CPU模板核函数（Kernel）"},{"level":2,"title":"更多进阶用法","slug":"更多进阶用法","link":"#更多进阶用法"}],"lastUpdated":1787050286000}'),o={name:"guide/programming_guide/programming_model/ai_cpu_programming.md"};function r(s,a,c,_,p,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<div><article class="markdown-body"><h1>AI CPU编程<span id="ZH-CN_TOPIC_0000002509743871"></span></h1><p>AI CPU是位于Device侧ARM64架构的处理器，其具备与AI Core相同的内存访问能力，可直接访问Device侧内存资源；也可以与Host侧的CPU一样，进行类似的数据计算，通常作为AI Core的补充，主要承担非矩阵类、逻辑比较复杂的分支密集型计算。AI CPU的运行环境为基础的Linux环境，编程时可使用libc库，C++标准库，STL模板库等。其硬件架构图如下所示：</p><p><strong>图1</strong> AI CPU硬件架构图<span id="fig1146075111341"></span><br><img src="'+n+`" alt title="AI-CPU硬件架构图"></p><p>本节介绍的AI CPU编程仅支持如下产品型号：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><h2 id="AI-CPU核函数（Kernel）定义">AI CPU核函数（Kernel）定义<span id="section4987175618443"></span><a class="header-anchor" href="#AI-CPU核函数（Kernel）定义">​</a></h2><p>在进行AI CPU编程时，与AI Core类似，同样需要定义设备侧函数入口（即核函数（Kernel）），该函数必须通过__aicpu__标识符进行声明，并且需与__global__标识符联合使用以表明其只能被Host侧调用。AI CPU的Device侧实现文件需要以.aicpu为后缀（或者以.cpp为后缀，在编译时增加-x aicpu选项）。该实现文件中包括上面介绍的核函数（Kernel）以及AI CPU普通函数定义，AI CPU普通函数无需添加执行空间标识符。</p><p>如下是一个AI CPU“Hello World”程序的示例，hello_world.aicpu文件内容如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 调用printf接口需要包含的头文件
#include &quot;aicpu_api.h&quot;

__global__ __aicpu__ uint32_t hello_world(void *args)
{
    AscendC::printf(&quot;Hello World!!!\\n&quot;);
    return 0;
}
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 编程时需要遵循如下规范：</p><ul><li>__aicpu__ __global__函数不能是void返回类型，并且入参只能是一个指针。</li><li>__aicpu__ __global__函数不能是类的成员函数，也不能存在于匿名空间下。</li><li>尽管AI CPU的核函数（Kernel）有返回值，但该返回值仅用于Runtime组件报告运行状态，开发者无需编写返回逻辑，也无法使用该返回值。因此，对于用户而言，AI CPU核函数（Kernel）等同于void类型，不能作为右值使用。</li></ul></div><h2 id="AI-CPU核函数（Kernel）调用">AI CPU核函数（Kernel）调用<span id="section178512255013"></span><a class="header-anchor" href="#AI-CPU核函数（Kernel）调用">​</a></h2><p>AI CPU核函数（Kernel）的调用需要在.asc文件中进行，和AI Core的算子调用类似，同样使用&lt;&lt;&lt;&gt;&gt;&gt;语法。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>hello_world&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(&amp;args, sizeof(KernelArgs));
</code></pre></div><ul><li>numBlocks：AI CPU Device侧暂不支持分核逻辑，因此Host侧调用多核无实际意义。建议设置为1。</li><li>l2ctrl：保留参数，当前固定为nullptr，开发者无需关注。</li><li>stream：类型为aclrtStream，stream用于维护一些异步操作的执行顺序，确保按照应用程序中的代码调用顺序在Device上执行。stream创建等管理接口请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 在编写调用代码时需要遵循如下规范：</p><ul><li>__aicpu__ __global__函数不能在.asc文件中进行定义，只能声明，且需要使用extern。</li><li>Host侧调用__global__ __aicpu__函数时必须使用&lt;&lt;&lt;&gt;&gt;&gt;异构调用语法，输入的函数入参在入参指针的基础上需要输入从指针中读取的数据大小。</li><li>在Host侧使用内核调用符&lt;&lt;&lt;...&gt;&gt;&gt;调用AI Core与AI CPU算子时不能使用同一条stream。</li></ul></div><p>加载和运行算子时，需要使用Runtime API，完成运行时管理和配置，详细内容请参考<a href="../compilation_and_execution/async_execution.html">算子运行</a>。AI CPU算子的编译请参考<a href="../compilation_and_execution/operator_compilation/ai_cpu_operator_compilation.html">AI CPU算子编译</a>。</p><h2 id="AI-CPU模板核函数（Kernel）">AI CPU模板核函数（Kernel）<span id="section135075471718"></span><a class="header-anchor" href="#AI-CPU模板核函数（Kernel）">​</a></h2><p>若需要使用模板核函数（Kernel），则需要在.aicpu文件中给出模板核函数（Kernel）的实例化声明，参考如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template&lt;typename T, int BUFF_SIZE&gt;
__global__ __aicpu__ uint32_t hello_world(void *args)
{
    AscendC::printf(&quot;Hello World!!!\\n&quot;);
    AscendC::printf(&quot;buffer_size is %d\\n&quot;, BUFF_SIZE);
    return 0;
}
template __global__ __aicpu__ uint32_t hello_world&lt;KernelArgs, 4096&gt;(void *args);
</code></pre></div><p>并在.asc文件中新增模板核函数（Kernel）实例化的extern声明：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template&lt;typename T, int BUFF_SIZE&gt;
extern __global__ __aicpu__ uint32_t hello_world(void *args);

template extern __global__ __aicpu__ uint32_t hello_world&lt;KernelArgs, 4096&gt;(void *args);
</code></pre></div><h2 id="更多进阶用法">更多进阶用法<span id="section109268265171"></span><a class="header-anchor" href="#更多进阶用法">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>更多AI CPU API的使用方法请参考<a href="../../../api/AI-CPU-API/AI-CPU-API.html">AI CPU API</a>。</p></div></article></div>`,1)])])}const u=e(o,[["render",r]]);export{g as __pageData,u as default};
